1	// test15.mjs — Node.js (ESM) port of test15.py.
2	//
3	// Mirrors the Python original exactly:
4	//   1. Parse --key1, --key2, --data (all required strings).
5	//   2. Encrypt the UTF-8 encoded data with key1 under AES-ECB.
6	//   3. Decrypt the resulting ciphertext with key2 (the "wrong" key).
7	//   4. Print the Python bytes-repr of both the ciphertext and the
8	//      wrong plaintext.
9	//
10	// Any error (bad arguments, invalid key size, data not a multiple of
11	// the block size) propagates uncaught so the process exits non-zero,
12	// matching the Python behavior of exiting 1 with a traceback on stderr.
13	
14	import { basename } from 'node:path';
15	import { fileURLToPath } from 'node:url';
16	
17	import { AESModeOfOperationECB } from './ecb_mode.mjs';
18	import { pyBytesRepr } from './pybytes.mjs';
19	import { parseArgs } from './argparse.mjs';
20	
21	// Python's str.encode() defaults to UTF-8. The inputs are ASCII in
22	// practice, but encode as UTF-8 to match Python semantics exactly.
23	function encodeUtf8(s) {
24	  return new TextEncoder().encode(s);
25	}
26	
27	function main() {
28	  // Python argparse derives the program name from basename(sys.argv[0]);
29	  // here that is the basename of this script file.
30	  const prog = basename(fileURLToPath(import.meta.url));
31	
32	  const args = parseArgs(prog, process.argv.slice(2), {
33	    key1: { type: 'str', required: true }, // First 16 bytes key
34	    key2: { type: 'str', required: true }, // Second 16 bytes key
35	    data: { type: 'str', required: true }, // 16 bytes data
36	  });
37	
38	  // Encrypt with first key, decrypt with second key
39	  const aes1 = new AESModeOfOperationECB(encodeUtf8(args.key1)); // Initialize first AES ECB cipher
40	  const aes2 = new AESModeOfOperationECB(encodeUtf8(args.key2)); // Initialize second AES ECB cipher
41	  const ciphertext = aes1.encrypt(encodeUtf8(args.data)); // Encrypt with first key
42	  const wrongPlaintext = aes2.decrypt(ciphertext); // Try to decrypt with wrong key
43	  console.log(pyBytesRepr(ciphertext));
44	  console.log(pyBytesRepr(wrongPlaintext));
45	}
46	
47	main();

